	@TestFactory
	Stream<DynamicTest> solutionModifiersDoNotBecomeTemplateTriples() {
		return Stream.of(
				"ORDER BY EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?value } }",
				"ORDER BY NOT EXISTS { ?s <urn:modifier> ?value OPTIONAL { ?value <urn:q> ?v } }",
				"ORDER BY EXISTS { { SELECT ?s WHERE { ?s <urn:modifier> ?value } } }",
				"GROUP BY ?s ?p ?o HAVING (EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?value } })",
				"ORDER BY EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?value } } LIMIT 1 OFFSET 1 "
						+ "VALUES ?o { <urn:o> }")
				.flatMap(modifiers -> Stream.of(QueryParseOptions.DEFAULT, QueryParseOptions.STRICT)
						.map(options -> DynamicTest.dynamicTest(options + ": " + modifiers, () -> {
							QueryRoot root = assertInstanceOf(QueryRoot.class,
									parser.parseQuery("CONSTRUCT WHERE { ?s ?p ?o } " + modifiers, null, options)
											.getTupleExpr());
							Projection projection = assertInstanceOf(Projection.class, root.getArg(),
									"Only the WHERE triple belongs to the template; extra triples create MultiProjection");
							assertEquals(List.of("subject", "predicate", "object"), projection.getProjectionElemList()
									.getElements()
									.stream()
									.map(element -> element.getProjectionAlias().orElse(element.getName()))
									.toList());
						})));
	}

	@Test
	void emptyShorthandTemplateIgnoresModifierTriples() {
		QueryRoot root = assertInstanceOf(QueryRoot.class, parser.parseQuery(
				"CONSTRUCT WHERE {} ORDER BY EXISTS { GRAPH <urn:g> { ?s ?p ?o } }", null).getTupleExpr());
		assertInstanceOf(EmptySet.class, root.getArg());
	}

	@Test
	void shorthandWherePreservesAstShapeAndRawOffsets() throws Exception {
		String query = "BASE <urn:base:\\u0061>\r\nCONSTRUCT FROM <urn:source> WHERE # { comment\r\n"
				+ "{ ?s <urn:p> \"literal } brace\" } ORDER BY ?s";
		ASTConstructQuery construct = assertInstanceOf(ASTConstructQuery.class,
				SyntaxTreeBuilder.parseQuery(query).getQuery());
		ASTWhereClause where = construct.getWhereClause();
		assertEquals(query.indexOf("{ ?s"), where.getGroupStartOffset());
		assertEquals(query.indexOf("} ORDER"), where.getGroupEndOffset());
		assertInstanceOf(ASTBasicGraphPattern.class, where.getGraphPatternGroup().jjtGetChild(0));
	}
